SELECT medpayment2_1.hcpcs_code AS hcpcs_code,   medpayment2_1.hcpcs_description AS hcpcs_description,   medpayment2_1.nppes_provider_state AS nppes_provider_state,   SUM(medpayment2_1.calculation_0820513143749095) AS sum_calculation_0820513143749095_ok,   SUM(medpayment2_1.average_submitted_chrg_amt) AS sum_average_submitted_chrg_amt_ok FROM medpayment2_1 WHERE ((medpayment2_1.hcpcs_code = '27447') AND (medpayment2_1.hcpcs_description = 'Total knee arthroplasty')) GROUP BY medpayment2_1.hcpcs_code,   medpayment2_1.hcpcs_description, medpayment2_1.nppes_provider_state;
